#![cfg(feature = "schema-import")]

use std::{fs, path::Path, process::Command};

fn fixture(root: &Path) -> std::path::PathBuf {
    let business = root.join("crates/orders-business");
    fs::create_dir_all(business.join("src")).unwrap();
    fs::write(
        root.join("Cargo.toml"),
        "[workspace]\nmembers=['crates/orders-business']\n",
    )
    .unwrap();
    fs::write(
        root.join("Cargo.lock"),
        "# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\nversion = 4\n\n[[package]]\nname = \"orders-business\"\nversion = \"0.1.0\"\n",
    )
    .unwrap();
    fs::write(business.join("Cargo.toml"), "[package]\nname='orders-business'\nversion='0.1.0'\nedition='2024'\n[package.metadata.ryframe]\nkind='business'\nmodule='orders'\n").unwrap();
    fs::write(business.join("src/lib.rs"), "").unwrap();
    let directory = root.join("目标 配置");
    fs::create_dir(&directory).unwrap();
    let mut document: toml::Table =
        toml::from_str(include_str!("../../../config/app.toml")).unwrap();
    document.insert("snowflake_worker_id".into(), toml::Value::Integer(1));
    let database = document["database"].as_table_mut().unwrap();
    let mut source = database["primary"].as_table().unwrap().clone();
    source.insert("name".into(), "legacy".into());
    source.insert("database".into(), "source_schema".into());
    database.insert("sources".into(), toml::Value::Array(vec![source.into()]));
    let target: toml::Table = toml::from_str("key='legacy'\nmode='dedicated'\nkind='mysql'\nhost='127.0.0.1'\ndatabase='tenant_schema'\nusername='root'\npassword=''\n").unwrap();
    document["tenant_data"]
        .as_table_mut()
        .unwrap()
        .insert("targets".into(), toml::Value::Array(vec![target.into()]));
    fs::write(
        directory.join("app.toml"),
        toml::to_string(&document).unwrap(),
    )
    .unwrap();
    fs::write(directory.join("app.dev.toml"), "").unwrap();
    directory
}

#[test]
fn file_config_uses_direct_target_password_and_rejects_source_ambiguity_without_connecting() {
    let root = tempfile::tempdir().unwrap();
    let directory = fixture(root.path());
    let before = [
        root.path().join("Cargo.toml"),
        root.path().join("Cargo.lock"),
        root.path().join("crates/orders-business/Cargo.toml"),
        root.path().join("crates/orders-business/src/lib.rs"),
        directory.join("app.toml"),
        directory.join("app.dev.toml"),
    ]
    .map(|path| {
        let bytes = fs::read(&path).unwrap();
        (path, bytes)
    });
    for (source, database, expected) in [
        ("legacy", "control", "同时匹配控制库 source 与租户 target"),
        ("legacy", "tenant", "同时匹配控制库 source 与租户 target"),
        (
            "sources.missing",
            "tenant",
            "未找到结构来源 database.sources[missing]",
        ),
        (
            "tenant_data.targets.missing",
            "control",
            "无法取得结构来源 tenant_data.targets.missing",
        ),
    ] {
        let output = Command::new(env!("CARGO_BIN_EXE_ryframe-generate"))
            .args([
                "import",
                "--package",
                "orders-business",
                "--database",
                database,
                "--connection",
                source,
                "--tables",
                "table1,table2",
                "--config-dir",
            ])
            .arg(&directory)
            .env("APP_ENV", "dev")
            .current_dir(root.path().join("crates/orders-business/src"))
            .output()
            .unwrap();
        assert_eq!(output.status.code(), Some(2));
        let error = String::from_utf8_lossy(&output.stderr);
        assert!(error.contains(expected), "{error}");
        assert!(!root.path().join(".local-tests").exists());
        assert!(!root.path().join("target").exists());
        for (path, bytes) in &before {
            assert_eq!(fs::read(path).unwrap(), *bytes, "{} 被修改", path.display());
        }
    }
}
